    --alert-caution-bg: #f0d0d0;
    --alert-caution-bar: #b22222;
    --drawer-bg: #efe6d0;
}
body.sepia :is(.hljs-keyword,.hljs-selector-tag,.hljs-literal) { color: #8b0000; }
body.sepia :is(.hljs-type,.hljs-title,.hljs-built_in) { color: #8b4513; }
body.sepia :is(.hljs-string,.hljs-regexp,.hljs-attr) { color: #2e8b57; }
body.sepia :is(.hljs-comment,.hljs-quote) { color: #8b7355; font-style: italic; }
body.sepia :is(.hljs-number,.hljs-symbol) { color: #006400; }
body.sepia .hljs-meta { color: #4b0082; }
body.sepia :is(.hljs-operator,.hljs-punctuation) { color: #5b4636; }

